 return f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Carriers of the Cross — a Christian-led, family-friendly WoW Forever guild on the PvE Alliance. Fellowship, friendship, and shared adventures."><meta name="theme-color" content="#102d40"><title>{title} | Carriers of the Cross</title><link rel="icon" href="/crest.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/epic.css"></head><body><a class="skip" href="#main">Skip to content</a><header><div class="nav"><a href="/" class="brand"><span class="crest" aria-hidden="true">✝</span><span>CARRIERS<br>OF THE CROSS</span></a><button class="menu" aria-label="Toggle navigation" aria-expanded="false" aria-controls="navigation">Menu ☰</button><nav id="navigation" class="navlinks" aria-label="Main navigation">{nav}<a class="button" href="https://discord.gg/Q3vse3prFg">Join our Discord ↗</a></nav></div></header><main id="main">{body}</main><footer><div class="foot"><div>Carriers of the Cross<br>Christian-led. Family-friendly. Adventure together.</div><div><a href="/statement-of-faith.html">Statement of Faith</a><a href="/community-rules.html">Community Rules</a><a href="https://discord.gg/Q3vse3prFg">Discord ↗</a><p style="margin-top:12px">An independent guild community. Not affiliated with Blizzard Entertainment.</p></div></div></footer><script src="/site.js"></script></body></html>'''
