guides=[('01','Our charter','The mission, vision, and values behind every shared adventure.','charter'),('02','What we believe','Scripture, the Apostles’ Creed, and grace in our differences.','statement-of-faith'),('03','Community rules','The standards that keep our fellowship welcoming and family-friendly.','community-rules'),('04','Membership','Who belongs here and how to get connected.','membership'),('05','Servant leadership','How our leaders care for and protect the community.','leadership'),('06','Guild ranks','A path from getting acquainted to serving others.','guild-ranks')]
cards='<nav class="guidegrid" aria-label="Explore the guild guide">'+''.join(f'<a class="guide" href="/{s}.html" aria-labelledby="guide-{s}"><h3 id="guide-{s}">{t}</h3><p>{p}</p><span class="guide-action" aria-hidden="true">Read {t.lower()} <span>→</span></span></a>' for n,t,p,s in guides)+'</nav>'
home='''<section class="hero"><img class="landscape" src="/assets/hero-epic.webp" alt="An Alliance champion in blue and gold armor and a crimson cross tabard before a grand fantasy city"><div class="heroinner"><div class="eyebrow">WoW Forever · Christian-led · Family-friendly</div><h1>Carriers<span class="of">of the</span><span class="cross">Cross</span></h1><p class="oath">Stand with us,<br>as we stand with Christ.</p><p>A Christian-led, family-friendly guild where the people behind the characters matter. Find fellowship, encouragement, and a place to call home in Azeroth.</p><div class="actions"><a class="button" href="https://discord.gg/Q3vse3prFg">Find us on Discord ↗</a><a class="button outline" href="/about.html">Get to know us →</a></div><div class="herofoot"><span><small>REGION</small>America</span><span><small>RULESET</small>PvE</span><span><small>FACTION</small>Alliance</span></div></div></section><div class="verse"><p>“So, whether you eat or drink, or whatever you do, do all to the glory of God.”</p><small>1 CORINTHIANS 10:31</small></div><section class="wrap"><div class="intro"><div><div class="sectionlabel">More than a guild name</div><h2>A community to<br>journey with.</h2></div><div><p>We’re here to enjoy World of Warcraft together—and to represent Christ in the way we do it. From a quiet evening of questing to a dungeon run that goes sideways, friendship and fellowship are at the heart of CotC.</p><p>You don’t have to be a Christian to join. You’re welcome to play, ask questions, and build friendships while respecting the Christian identity and standards of our community.</p><a class="textlink" href="/charter.html">Read our mission & values →</a></div></div><div class="values"><div><span class="number">01</span><h3>Faith lived openly</h3><p>Talk about Scripture, share a prayer request, and encourage one another. Faith is part of who we are.</p></div><div><span class="number">02</span><h3>A place for families</h3><p>PG conversations, kindness, and respect. An atmosphere where families can comfortably play together.</p></div><div><span class="number">03</span><h3>People before pixels</h3><p>Welcome someone new. Lend a hand. Invite another player along. The best loot is the friendships we keep.</p></div></div></section><section class="dark"><div class="wrap community"><div class="banner"><img src="/assets/guild-banner.png" alt="Carriers of the Cross guild banner: an Alliance knight bearing a cross, America region, PvE ruleset, Alliance faction. Stand with us, as we stand with Christ." loading="lazy"></div><div><div class="sectionlabel">Life in Carriers of the Cross</div><h2>The journey is better<br>with good company.</h2><p>Some of us level quickly. Others take the scenic route. We make room for shared adventures, conversations about faith, prayer, and simply enjoying each other’s company.</p><p>Discord keeps us connected beyond the game, with space to organize groups, share encouragement, and get to know the people behind the characters.</p><a class="textlink" href="/guild-life.html">Explore guild life →</a></div></div></section><section class="wrap guild-guide" aria-labelledby="guild-guide-heading"><div class="sectionlabel">Know the community</div><h2 id="guild-guide-heading">Your guide to CotC.</h2><p class="guide-intro">Get to know our beliefs, community standards, and how the guild works. Choose a topic below to read the full guide.</p>'''+cards+'''</section><section class="join"><div class="wrap"><div class="sectionlabel">Your next adventure starts with hello</div><h2>Come for the game.<br>Stay for the fellowship.</h2><p>Read through our community guide, then join us on Discord and introduce yourself. We’d love to get to know you.</p><a class="button" href="https://discord.gg/Q3vse3prFg">Join our Discord ↗</a></div></section>'''
(d/'index.html').write_text(shell('Home',home))
def inline(s):
 s=html.escape(s)
 s=re.sub(r'\[([^\]]+)\]\(([^)]+)\)',lambda m:'<a href="'+m[2].replace('https://cotc.guildtag.com/wiki/about-carriers-of-the-cross/','/about.html').replace('https://cotc.guildtag.com/wiki/community-rules/','/community-rules.html').replace('https://cotc.guildtag.com/wiki/statement-of-faith/','/statement-of-faith.html')+'">'+m[1]+'</a>',s)
 s=re.sub(r'\*\*(.+?)\*\*',r'<strong>\1</strong>',s);s=re.sub(r'\*(.+?)\*',r'<em>\1</em>',s)
 return s
 defunused=0
def md(s):
 out=[]
 for b in re.split(r'\n\s*\n',s.strip()):
  if b.startswith('### '):out.append('<h3>'+inline(b[4:])+'</h3>')
  elif b.startswith('## '):out.append('<h2>'+inline(b[3:])+'</h2>')
  elif b.startswith('# '):out.append('<h2>'+inline(b[2:])+'</h2>')
  elif b.startswith('>'):out.append('<blockquote><p>'+ '<br>'.join(inline(x.lstrip('> ')) for x in b.splitlines())+'</p></blockquote>')
  elif b.startswith('* ') or b.startswith('- '):out.append('<ul>'+''.join('<li>'+inline(x[2:])+'</li>' for x in b.splitlines())+'</ul>')
  elif b=='---':out.append('<hr>')
  else:out.append('<p>'+inline(b).replace('\n','<br>')+'</p>')
 return '\n'.join(out)
def page(title,desc,body,slug):
 sidebar=''.join(f'<a href="/{s}.html" '+('aria-current="page"' if s==slug else '')+f'>{t}</a>' for t,s in side)
 content=f'<section class="pagehero"><div><div class="eyebrow">Carriers of the Cross / The guild guide</div><h1>{title}</h1><p>{desc}</p></div></section><div class="docs"><aside class="sidebar"><nav aria-label="Guild guide">{sidebar}</nav></aside><article class="prose">{body}</article></div>'
 (d/(slug+'.html')).write_text(shell(title,content,slug))
for slug,title,desc in [('about-carriers-of-the-cross','Our Guild','Who we are, where we came from, and why we carry the name.'),('guild-life','Guild Life','Shared adventures, everyday friendship, and faith lived together.'),('statement-of-faith','Statement of Faith','Historic Christian faith. Scripture as our final authority.'),('community-rules','Community Rules','Clear expectations, rooted in love for God and one another.')]:
 data=json.load(open(root/'content'/(slug+'.json')))['wikiPage'];body=data['body']
 # Use the current Drive mission, as requested for this new site.
 if slug=='about-carriers-of-the-cross':body=body.replace('To provide a fun and safe Christian community for World of Warcraft players that glorifies Christ.','To glorify God by building a Christ-centered, family-friendly World of Warcraft community where players develop meaningful friendships, encourage one another in faith, and enjoy the game together.')
 page(title,desc,md(body),'about' if slug=='about-carriers-of-the-cross' else slug)
charter=(root/'charter.txt').read_text().split('Guild Ranks')[0].replace('Guild Charter\n','',1)
charter=re.sub(r'(?m)^(\d\. .+?)(?: \(.+?\))?$',r'## \1',charter)
charter=re.sub(r'(?m)^## ([1-5]\. (?:Christ First|Genuine Fellowship|Love One Another|Biblical Integrity|Unity in Community))$',r'### \1',charter)
# Separate headings and source paragraphs for readable static rendering.
charter=re.sub(r'(?m)^(#{2,3} .+)$',r'\n\1\n',charter)
page('Our Charter','Our mission, vision, values, and commitment to a healthy Christian gaming community.',md(charter),'charter')
page('Membership','A Christian community with an open seat at the table.','''<h2>Who belongs here?</h2><p>CotC is a distinctly Christian guild that welcomes both Christians and non-Christians who wish to participate in our community and respect its values.</p><p>Membership and ordinary rank advancement do not require a profession of Christian faith. Positions of spiritual and organizational leadership require Christian faith and biblical maturity.</p><p>We will not assume every member shares our beliefs, nor treat non-Christian members as second-class participants. Our desire is that everyone experiences genuine kindness, humility, and the love of Christ.</p><h2>Get connected</h2><ol><li>Read our <a href="/community-rules.html">Community Rules</a> and <a href="/statement-of-faith.html">Statement of Faith</a> to understand the community.</li><li>Join our Discord and introduce yourself.</li><li>Open a ticket in the <strong>#help-desk</strong> channel in Discord and include your character name. Someone with invite privileges will coordinate a guild invite with you.</li><li>Join in the conversation, invite someone to group, and get to know your guildmates.</li></ol><p><a class="button" href="https://discord.gg/Q3vse3prFg">Join our Discord ↗</a></p><h2>Common questions</h2><details><summary>Do I have to be a Christian?</summary><p>No. Everyone is welcome who respects our Christian identity and follows our community standards.</p></details><details><summary>What does family-friendly mean?</summary><p>We keep conversation PG, avoid profanity and explicit content, and treat others with kindness. Our full Community Rules explain the standards.</p></details><details><summary>Do I need to register on this website?</summary><p>No. This website is our information hub. Connect with the community through Discord and in-game.</p></details><details><summary>Do I need to keep up with everyone else?</summary><p>No. Some members level quickly and others take their time. There is room for different ways to enjoy the game, and participation in events is optional.</p></details>''','membership')
page('Servant Leadership','Leaders exist to serve the community, not to be served by it.','''<h2>Character before authority</h2><p>A leader’s success should be measured by the health of the community, not their rank or authority.</p><p>CotC leaders should demonstrate:</p><ul><li><strong>Humility:</strong> putting the needs of others ahead of personal recognition.</li><li><strong>Commitment:</strong> believing in and actively supporting the guild’s mission.</li><li><strong>Emotional maturity:</strong> listening well, handling conflict wisely, and treating people with grace.</li><li><strong>Biblical maturity:</strong> demonstrating a growing relationship with Christ and sound biblical judgment.</li><li><strong>Active participation:</strong> playing alongside members, building relationships, and sometimes setting aside personal gameplay goals to serve others.</li></ul><h2>Protecting the community</h2><p>Moderators help protect guild chat and Discord. Officers participate in leadership meetings and decisions, helping shape the guild’s future. The Guild Master serves as tie breaker.</p><p>Spiritual and organizational leaders are expected to be Christians with biblical maturity. Moderator requirements include sharing a testimony with the Officers and affirming the Statement of Faith.</p><h2>Questions or concerns?</h2><p>Reach out to an Officer in-game or through Discord. Please handle personal concerns privately and treat information shared in confidence with care.</p><a class="textlink" href="/guild-ranks.html">See rank requirements & responsibilities →</a>''','leadership')
ranks=[('Peon','Family-friendly name.','Follow the Community Rules.','Speak in guild chat.'),('Farmer','Join Discord and connect Discord to Battle.net.','Continue following the Community Rules.','As above.'),('Squire','Guild member for 2 weeks; download Guild Fellowship; active communication or involvement in guild activities.','Participate in the community.','As above.'),('Knight','Squire for 2 weeks; display good character.','Be willing to invite members when asked.','Invite members.'),('Steward','Knight for 2 weeks; volunteer to steward the guild bank.','Be a good steward of guild resources.','Additional guild bank permissions.'),('Veteran','Knight or Steward for 2 weeks; volunteer to lead activities. Depending on the role, testimony and Statement of Faith approval may be required.','Lead respectfully and maintain positive relationships with members and Officers.','Withdraw gold.'),('Moderator','Knight, Steward, or Veteran for 2 weeks; share testimony; affirm Statement of Faith; volunteer to moderate.','Protect the community and refer issues to Officers when needed.','Demote or remove members.'),('Officer','Moderator for 2 weeks.','Participate in Officer meetings and decision making; help shape the guild.','Officer status, promotions, and bank tab management.'),('Guild Master','—','Tie breaker.','Officer status, promotions, and bank tab management.'),('Purgatory','None.','Restricted status used for moderation and further Officer intervention.','None.')]
